{{ config(materialized = 'view') }}

-- RAW -> dim_customers: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: profiled as unique: ORDER_ID (confirm business keys in the STTM).

with sp_dim_customers as (
    select
        upper(trim(o.ORDER_ID::varchar)) as source_unique_id,
        o.ORDER_ID as order_id,
        o.CUSTOMER_ID as customer_id,
        nullif(trim(o.ORDER_DATE), '') as order_date,
        nullif(trim(o.ORDER_STATUS), '') as order_status,
        nullif(trim(o.TOTAL_AMOUNT), '') as total_amount,
        nullif(trim(o.SHIPPING_ADDRESS), '') as shipping_address,
        nullif(trim(o.PAYMENT_METHOD), '') as payment_method,
        nullif(trim(o.SOURCE_SYSTEM), '') as source_system,
        j1.ORDER_ITEM_ID as order_item_id,
        j1.PRODUCT_ID as product_id,
        j1.QUANTITY as quantity,
        j1.UNIT_PRICE as unit_price,
        j1.DISCOUNT_PCT as discount_pct,
        nullif(trim(j2.PRODUCT_NAME), '') as product_name,
        nullif(trim(j2.CATEGORY), '') as category,
        nullif(trim(j2.SUB_CATEGORY), '') as sub_category,
        j2.SUPPLIER_ID as supplier_id,
        nullif(trim(j2.CREATED_DATE), '') as created_date,
        nullif(trim(j3.METADATA_FILENAME), '') as metadata_filename,
        j3.METADATA_ROW_NUMBER as metadata_row_number
    from {{ source('dim_customers_raw_source', 'raw_orders') }} as o
    left join {{ source('dim_customers_raw_source', 'raw_order_items') }} as j1 /* 1:N */
        on o.ORDER_ID = j1.ORDER_ID
    left join {{ source('dim_customers_raw_source', 'raw_products') }} as j2 /* N:1 */
        on j1.PRODUCT_ID = j2.PRODUCT_ID
    left join {{ source('dim_customers_raw_source', 'raw_website_events') }} as j3 /* N:1 */
        on j1.QUANTITY = j3.METADATA_ROW_NUMBER
    where nullif(upper(trim(o.ORDER_ID::varchar)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ORDER_ID::varchar)) order by source_unique_id) = 1
),

base as (
    select
        o.source_unique_id,
        null as raw_data /* TODO: no join path to RAW_CUSTOMERS */,
        null as source_file /* TODO: no join path to RAW_CUSTOMERS */,
        null as load_timestamp /* TODO: no join path to RAW_CUSTOMERS */,
        null as record_metadata /* TODO: no join path to RAW_CUSTOMERS */,
        null as event_data /* TODO: no join path to RAW_EVENTS */,
        null as event_type /* TODO: no join path to RAW_EVENTS */,
        null as received_at /* TODO: no join path to RAW_EVENTS */,
        o.order_id as order_id,
        o.customer_id as customer_id,
        o.order_date as order_date,
        o.order_status as order_status,
        o.total_amount as total_amount,
        o.shipping_address as shipping_address,
        o.payment_method as payment_method,
        o.source_system as source_system,
        o.order_item_id as order_item_id,
        o.product_id as product_id,
        o.quantity as quantity,
        o.unit_price as unit_price,
        o.discount_pct as discount_pct,
        o.product_name as product_name,
        o.category as category,
        o.sub_category as sub_category,
        o.supplier_id as supplier_id,
        true as is_active,
        o.created_date as created_date,
        o.metadata_filename as metadata_filename,
        o.metadata_row_number as metadata_row_number
    from sp_dim_customers as o
)

select
    source_unique_id,
    raw_data,
    source_file,
    load_timestamp,
    record_metadata,
    event_data,
    event_type,
    received_at,
    order_id,
    customer_id,
    order_date,
    order_status,
    total_amount,
    shipping_address,
    payment_method,
    source_system,
    order_item_id,
    product_id,
    quantity,
    unit_price,
    discount_pct,
    product_name,
    category,
    sub_category,
    supplier_id,
    is_active,
    created_date,
    metadata_filename,
    metadata_row_number
from base
